import sys
import flax.linen as nn
import jax.numpy as jnp
import optax

# Using Ariadne's shared module now that I understand its contents
sys.path.append('storage/ariadne')
from models_fourier_ramp import FourierForecasterLN_Ramp

# Wrapper class is necessary to handle the RNG correctly for dropout
class ModelWrapper:
    def __init__(self, hparams):
        self.model = FourierForecasterLN_Ramp(
            rank_k=hparams.get('rank_k'),
            proj_rank=hparams.get('proj_rank'),
            hidden_size=hparams.get('hidden_size'),
            drop=hparams.get('drop'),
            gamma_start=hparams.get('gamma_start'),
            gamma_end=hparams.get('gamma_end'),
            learn_gamma=hparams.get('learn_gamma')
        )
        self.needs_rng = True

    def init(self, rng_key, dummy_input):
        return self.model.init({'params': rng_key, 'dropout': rng_key}, dummy_input, training=True)

    def apply(self, params, x, training=False, mutable=None, rngs=None):
        return self.model.apply(params, x, training=training, rngs=(rngs or {}))

def create_network(hparams):
    return ModelWrapper(hparams)

# Using the exact hyperparameters from the SOTA submission ID 411
def _define_hyperparameters():
    return {
        'learning_rate': 9e-4,
        'rank_k': 320,
        'proj_rank': 36,
        'hidden_size': 160, # From SOTA ID 411
        'drop': 0.05,
        'gamma_start': 0.25,
        'gamma_end': 0.99,
        'learn_gamma': False
    }

def compute_loss(predictions, targets, params, x):
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    curv_pen = jnp.mean(curv * curv)
    return mae + 1e-4 * curv_pen

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate)
    )
